/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: LookupProgress
 * Internal
 *   Types: Timeline, Step, Text
 *   Functions: evidence, Nothing, ReloadAlert
 *   Constants: STAGES, EvidenceStep, EvidenceBasis, EvidenceBridgeNote, EvidenceAlert
 *   Variables: evidenceChunk
 * @end-catalog */

import { lazy, Suspense, useId, useRef, useState, type ReactNode } from 'react';
import { Link } from 'react-router';
import { useLocalization } from '../../localization/LocalizationProvider';
import { useAdminText } from './AdminAccess';
import type { ReviewLookupView } from './importLookupApi';
import type { EvidenceStepText } from './LookupEvidence';
import { evidenceBasis, gateWaitSeconds, identifierStep, lookupRecord, searchedTexts, titleSearch } from './lookupProgressModel';
import styles from './adminStyles';

type Timeline = NonNullable<ReviewLookupView['timeline']>;
type Step = Timeline['steps'][number];
type Text = NonNullable<Step['texts']>[number];
/** The stages whose counts name their own unit. */
const STAGES: readonly string[] = ['details', 'itunes', 'bridge', 'aliases'];
/**
 * The import-evidence words load once, only for a run that used the review's captured identifiers. A chunk that cannot load leaves
 * their rows and lines empty, and EvidenceAlert asks for a reload once, above the list.
 */
let evidenceChunk: Promise<typeof import('./LookupEvidence')> | null = null;
const evidence = () => evidenceChunk ??= import('./LookupEvidence');
const Nothing = () => null;
function ReloadAlert() {
  const t = useAdminText();
  return <div role="alert"><p>{t('common.reload')}</p>
    <button className={styles.button} type="button" onClick={() => window.location.reload()}>{t('common.reload_action')}</button></div>;
}
const EvidenceStep = lazy(() => evidence().then(module => ({ default: module.LookupEvidenceStep }), () => ({ default: Nothing })));
const EvidenceBasis = lazy(() => evidence().then(module => ({ default: module.LookupEvidenceBasis }), () => ({ default: Nothing })));
const EvidenceBridgeNote = lazy(() => evidence().then(module => ({ default: module.LookupEvidenceBridgeNote }), () => ({ default: Nothing })));
const EvidenceAlert = lazy(() => evidence().then(module => ({ default: module.LookupEvidenceAlert }), () => ({ default: ReloadAlert })));

/**
 * The Details log of an existing-Album review's lookup run (its own lazy chunk, review only; when it cannot load, the status line
 * renders nothing in its place, or asks for a reload where it would carry the Album link). While a run is queued, running or
 * retrying, the log stays short (design v3, two lines): the status line's `notes` on one line (the time it has waited or run, that
 * it keeps running after the page is left), while a running run has shown no new step for more than five seconds of this page's
 * clock (`now`, the summary's last read) that it waits for MusicBrainz (iTunes in the iTunes phase), and only the step in progress
 * (else the last one reached) with what it searched, its state and counts (each stage naming what it counts, the bridge also the
 * titles it found). Once the run ends the full step list appears: its record (time taken, the MusicBrainz name searches and iTunes
 * searches sent, and releases examined), then, after a run that completed with no issue, the names it searched, then every step;
 * any other ended run, also one that completed after MusicBrainz's retries ran out, shows its steps the same way without the names. A search the run may not have sent reads as such and is never named or counted. A search of the review's
 * captured import evidence names only its basis (LookupEvidence.tsx, its own chunk loaded only for such a run; when it cannot
 * load, one alert above the list asks for a reload), and a completed run whose release one of them preselected says which on a
 * line under the status that stays in view while the log is folded. An iTunes step
 * that left results out of the comparison, and a bridge step naming the titles iTunes returned (for the names searched, or for
 * the captured barcode), add a line saying so. With
 * `albumHref` (a run that ended because the Album changed) the link to open the Album and start a new completion stays in view,
 * also without a timeline. The log is no live region, as every poll changes it.
 *
 * It renders inside the status line (`styles.statusLine`, which puts each block after the headline on its own line): where the
 * run has a timeline, a Details / Hide details text button on the headline's right, then the log as a block on the line's full
 * width. The log starts shown while a run is active or after one that failed (unavailable or stopped) and hidden after one that
 * completed or was superseded; the administrator's choice holds until the run or that state changes. A hidden log stays mounted,
 * so the wait keeps counting from when this page first saw the last step.
 */
export function LookupProgress({ lookup, now, notes = [], albumHref }: { lookup: ReviewLookupView; now: number; notes?: readonly string[]; albumHref: string | null }) {
  const t = useAdminText(), { locale } = useLocalization(), id = useId(), timeline = lookup.timeline;
  // When this page first saw the run's current last step, on its own clock.
  const seen = useRef<{ at: string; since: number } | null>(null);
  if (timeline && seen.current?.at !== timeline.updatedAt) seen.current = { at: timeline.updatedAt, since: now };
  const link = albumHref && <div className={styles.actions}><Link className={`${styles.link} ${styles.primary}`} to={albumHref}>{t('catalog_review.lookup_superseded_open')}</Link></div>;
  const active = lookup.state === 'queued' || lookup.state === 'running' || lookup.state === 'retrying';
  // The administrator's Details choice, for this run in this state (an active run's states count as one).
  const shown = `${lookup.run}:${active ? 'active' : lookup.state}`, [choice, setChoice] = useState<{ shown: string; open: boolean } | null>(null);
  const open = choice?.shown === shown ? choice.open : active || lookup.state === 'unavailable' || lookup.state === 'stopped';
  const button = timeline && <button className={styles.textButton} type="button" style={{ whiteSpace: 'nowrap' }} aria-expanded={open} aria-controls={`${id}-log`}
    onClick={() => setChoice({ shown, open: !open })}>{t(open ? 'catalog_review.lookup_log_hide' : 'catalog_review.lookup_log_show')}</button>;
  // What follows the status and its button is a block, which the status row lays out on its full width.
  const below = (body: ReactNode) => <div>{body}</div>;
  const noted = notes.map(note => <p key={note} className={styles.meta}>{note}</p>);
  if (!timeline) return link || notes.length ? below(<>{link}{noted}</>) : null;
  const search = timeline.trackTitleSearch;
  const quote = (entry: Text) => t(entry.artist ? 'catalog_review.lookup_step_quoted_artist' : 'catalog_review.lookup_step_quoted', { text: entry.text, artist: entry.artist ?? '' });
  const titles = (step: Step) => new Intl.ListFormat(locale, { type: 'conjunction' }).format((step.texts ?? []).map(quote));
  const label = (step: Step) => step.kind === 'trackTitle' ? search?.state === 'skipped' ? t('catalog_review.lookup_step_track_title_skipped', { reason: search.reason })
      : search?.state === 'notNeeded' ? t('catalog_review.lookup_step_track_title_not_needed')
      : step.texts?.length ? t('catalog_review.lookup_step_track_title', { titles: titles(step) }) : t('catalog_review.lookup_step_track_title_plain')
    : step.kind === 'itunes' && step.state === 'skipped' ? t('catalog_review.lookup_step_itunes_skipped', { reason: lookup.itunes === 'unavailable' ? 'unavailable' : 'notNeeded' })
    : step.kind === 'bridge' && step.texts?.length ? t('catalog_review.lookup_step_bridge_titles', { titles: titles(step) })
    : !titleSearch(step) ? t(`catalog_review.lookup_step_${step.kind}`)
    : step.texts?.length ? t(`catalog_review.lookup_step_${step.kind}`, { text: step.texts[0].text, artist: step.texts[0].artist ?? '' }) : t('catalog_review.lookup_step_search');
  // A pending step of a run that ended was never run; a skipped Track-title search or iTunes fallback says why in its own words.
  const mark = (step: Step) => step.state === 'pending' && !active ? 'notRun' : step.state === 'skipped' && (step.kind === 'trackTitle' || step.kind === 'itunes') ? 'notTaken' : step.state;
  // Why releases of other titles were found: an iTunes step that left results out says only some were compared, and a bridge
  // step with titles says they are what iTunes returned for the names searched.
  const note = (step: Step) => step.kind === 'itunes' && step.partial ? t('catalog_review.lookup_step_itunes_partial')
    : step.kind === 'bridge' && step.texts?.length ? step.byBarcode ? <Suspense fallback={null}><EvidenceBridgeNote titles={titles(step)} /></Suspense>
      : t('catalog_review.lookup_step_bridge_note', { titles: titles(step) }) : null;
  // A stage's counts say what they count (releases read, iTunes searches, bridge checks, alias lookups); the bridge's also name the
  // titles it found.
  const counted = (step: Step, total: number) => STAGES.includes(step.kind) ? t(`catalog_review.lookup_step_counted_${step.kind}${step.kind === 'bridge' && step.texts?.length ? '_titles' : ''}`,
    { done: step.done ?? 0, total, titles: titles(step) }) : t('catalog_review.lookup_step_counted', { step: label(step), done: step.done ?? 0, total });
  // A search of the captured import evidence, Track titles found not needed in a run that had one, and Track titles those searches
  // left no room for, read in their own words.
  const evidenced = timeline.steps.some(identifierStep);
  const evidenceText = (step: Step): EvidenceStepText | null => step.kind === 'releaseId' ? step.from === 'tags' ? 'releaseIdTags' : 'releaseIdImport'
    : step.kind === 'barcode' || step.kind === 'catalogNumber' ? step.kind
    : step.kind !== 'trackTitle' ? null : search?.state === 'skipped' && search.reason === 'noRoom' ? 'trackTitleNoRoom'
    : evidenced && search?.state === 'notNeeded' ? 'trackTitleNotNeeded' : null;
  // Any row or line in those words: then the evidence chunk loads, and one alert asks for a reload when it cannot.
  const usesEvidence = timeline.steps.some(step => evidenceText(step) !== null || step.byBarcode === true);
  const alert = usesEvidence && <Suspense fallback={null}><EvidenceAlert /></Suspense>;
  const list = (steps: readonly Step[]) => <ol aria-label={t('catalog_review.lookup_steps')} className={styles.muted} style={{ listStyle: 'none', paddingLeft: 0 }}>{steps.map((step, index) => {
    const words = evidenceText(step);
    return words ? <li key={`${step.kind}${index}`}><Suspense fallback={null}><EvidenceStep text={words} mark={mark(step)} /></Suspense></li>
      : <li key={`${step.kind}${index}`}>{t(`catalog_review.lookup_step_${mark(step)}`, { step: step.total ? counted(step, step.total) : label(step) })}
        {note(step) && <span style={{ display: 'block', paddingInlineStart: '1.2em' }}>{note(step)}</span>}</li>;
  })}</ol>;
  const log = (body: ReactNode) => <div id={`${id}-log`} className={styles.lookupLog} hidden={!open}>{body}</div>;
  if (active) {
    // Short while it runs: the notes on one line and only the step in progress (else the last one reached), so the proposals
    // stay in the first screen; the full list follows once the run ends.
    const wait = gateWaitSeconds(lookup, now, seen.current!.since), running = timeline.steps.filter(step => step.state === 'active');
    const current = running.length ? running : timeline.steps.filter(step => step.state !== 'pending').slice(-1);
    return <>{button}{below(<>{alert}{log(<>{notes.length > 0 && <p className={styles.meta}>{notes.join(' · ')}</p>}
      {wait !== null && <p className={styles.muted}>{t('catalog_review.lookup_gate_wait', { source: lookup.progress?.phase === 'itunes' ? 'iTunes' : 'MusicBrainz', seconds: wait })}</p>}
      {current.length > 0 && list(current)}</>)}</>)}</>;
  }
  // A run that completed after MusicBrainz's retries ran out (its issue says so) may not have sent the searches it lists.
  const searched = lookup.state === 'complete' && lookup.issue === null ? searchedTexts(timeline) : [];
  const basis = lookup.state === 'complete' ? evidenceBasis(lookup) : null;
  // The identifier that chose the applied release stays in view while the log is folded, as other releases may still match.
  return <>{button}{below(<>{link}{(usesEvidence || basis) && <Suspense fallback={null}><EvidenceAlert />{basis && <EvidenceBasis basis={basis} />}</Suspense>}
    {log(<>{noted}<p className={styles.details}>{t('catalog_review.lookup_log', lookupRecord(lookup)!)}</p>
      {searched.length > 0 && <p className={styles.meta}>{t('catalog_review.lookup_searched', { searches: searched.map((entry, index) => index
        ? t(entry.artist ? 'catalog_review.lookup_searched_then' : 'catalog_review.lookup_searched_then_alone', { item: quote(entry) }) : quote(entry)).join('') })}</p>}
      {list(timeline.steps)}</>)}</>)}</>;
}
